=== SettingValue
package ly.com.tahaben.settings_portability

enum class SettingType { BOOLEAN, INT, LONG, FLOAT, DOUBLE, STRING, STRING_SET }

/**
 * One typed preference value. Int and Long are separate cases so a stored long never passes through a double
 * or an int (CLAIM(lossless-long)). A set compares as a set; its order is fixed only when written to a file.
 */
sealed interface SettingValue {
    val type: SettingType

    data class Bool(val value: Boolean) : SettingValue { override val type get() = SettingType.BOOLEAN }
    data class Int32(val value: Int) : SettingValue { override val type get() = SettingType.INT }
    data class Int64(val value: Long) : SettingValue { override val type get() = SettingType.LONG }
    data class Float32(val value: Float) : SettingValue { override val type get() = SettingType.FLOAT }
    data class Float64(val value: Double) : SettingValue { override val type get() = SettingType.DOUBLE }
    data class Text(val value: String) : SettingValue { override val type get() = SettingType.STRING }
    data class TextSet(val values: Set<String>) : SettingValue { override val type get() = SettingType.STRING_SET }
}
=== PortableSettings
package ly.com.tahaben.settings_portability

/** The two key-value stores that hold settings. Room configuration rows are separate ([ConfigurationRows]). */
enum class SettingsStoreId { SHARED_PREFERENCES, DATA_STORE }

/** Row of `apps_db`: a launcher activity. [userSerial] is only meaningful on the same device and user. */
data class AppActivityRow(
    val appName: String,
    val packageName: String,
    val activityName: String,
    val userSerial: Long,
)

/** Row of `TimeLimitEntity`. */
data class TimeLimitRow(
    val packageName: String,
    val timeLimitInMilli: Long,
    val timeAtAddingInMilli: Long,
)

/** Every configuration row. These two tables are the only SQL tables that hold settings. */
data class ConfigurationRows(
    val apps: List<AppActivityRow> = emptyList(),
    val timeLimits: List<TimeLimitRow> = emptyList(),
)

/** The complete configuration across all three stores: what an export holds and what an import replaces. */
data class SettingsConfiguration(
    val sharedPreferences: Map<String, SettingValue> = emptyMap(),
    val dataStore: Map<String, SettingValue> = emptyMap(),
    val rows: ConfigurationRows = ConfigurationRows(),
)

/** Where the settings came from. Informational; never used to decide what to apply. */
data class PortableSource(
    val packageName: String,
    val versionName: String,
    val versionCode: Long,
    val userId: Int,
)

/** A key found in the source that the catalog does not know. Name only: its value is never carried. */
data class UnsupportedKey(val store: SettingsStoreId, val key: String)

data class PortableSettings(
    val source: PortableSource,
    val configuration: SettingsConfiguration,
    val unsupportedKeys: List<UnsupportedKey> = emptyList(),
)

enum class ExclusionReason { SECRET, INTERNAL, HISTORY }

/** A key the catalog deliberately leaves out. Name only, for the preview. */
data class OmittedSetting(val store: SettingsStoreId, val key: String, val reason: ExclusionReason)

data class ConversionReport(val omitted: Set<OmittedSetting>)

enum class PortableSettingsErrorCode {
    MALFORMED_JSON,
    MALFORMED_XML,
    TOO_LARGE,
    TOO_MANY_ENTRIES,
    TOO_DEEP,
    WRONG_FORMAT,
    UNSUPPORTED_VERSION,
    DUPLICATE_KEY,
    TYPE_MISMATCH,
    OUT_OF_RANGE,
    EXCLUDED_KEY,
    UNSUPPORTED_KEY,
    SEMANTIC_REJECTED,
}

/** [location] names a store and key (for example `sharedPreferences/notification_flood_threshold`). Never a value. */
data class PortableSettingsError(val code: PortableSettingsErrorCode, val location: String)

sealed interface PortableSettingsResult {
    data class Ready(val settings: PortableSettings, val report: ConversionReport) : PortableSettingsResult
    data class Failed(val error: PortableSettingsError) : PortableSettingsResult
}
=== SettingsCatalog
package ly.com.tahaben.settings_portability

sealed interface SettingDisposition {
    /** A user setting. The stored value must have this type. */
    data class Configuration(val type: SettingType) : SettingDisposition

    /** Known and deliberately not transferred. */
    data class Excluded(val reason: ExclusionReason) : SettingDisposition

    /** Not in the catalog. Reported by name, never applied. */
    data object Unsupported : SettingDisposition
}

/**
 * The one list of which keys are settings. Export, rescue conversion, import validation and the
 * "replace only the configuration domain" rule all read it, so they cannot disagree.
 *
 * Required content (inventory in research/settings-portability-red-report.md): exact keys and key prefixes for
 * SharedPreferences `shared_pref` and the DataStore `farhan_data_store`.
 *
 * STUB: red phase. No behavior yet.
 */
object SettingsCatalog {
    fun dispositionOf(store: SettingsStoreId, key: String): SettingDisposition =
        SettingDisposition.Unsupported
}
=== PortableSettingsCodec
package ly.com.tahaben.settings_portability

/**
 * Bounds applied while reading, before anything large is allocated. [maxEntries] counts every preference entry,
 * every set element and every row across the document. [maxStringLength] bounds every parsed JSON key and string.
 */
data class DecodeLimits(
    val maxBytes: Int = 1 shl 20,
    val maxEntries: Int = 20_000,
    val maxDepth: Int = 8,
    val maxStringLength: Int = 262_144,
)

sealed interface DecodeResult {
    data class Valid(val settings: PortableSettings) : DecodeResult
    data class Invalid(val error: PortableSettingsError) : DecodeResult
}

/**
 * Versioned UTF-8 JSON file format, version 1. Structural checks only: format name, version, types, ranges,
 * duplicates, limits. Whether a key is a known setting is checked against [SettingsCatalog] by the importer.
 *
 * Invariants:
 *  - CLAIM(lossless-long): a long is written and read as exact integer digits, never as a double.
 *  - CLAIM(deterministic-file): the same [PortableSettings] always encodes to the same bytes (compact JSON,
 *    fixed member order, keys sorted, set elements sorted, rows sorted by primary key, unsupportedKeys sorted by
 *    store name ("dataStore" before "sharedPreferences") then key).
 *  - CLAIM(strict-input): a duplicate member name anywhere, a key in two type groups, a duplicate set element,
 *    an unknown version, a wrong type or range, trailing data, or a limit breach yields Invalid and no value.
 *
 * Shape: {"format":"farhan-settings","version":1,"source":{...},
 *   "sharedPreferences":{"booleans":{},"ints":{},"longs":{},"floats":{},"doubles":{},"strings":{},"stringSets":{}},
 *   "dataStore":{same groups},"configurationRows":{"apps":[],"timeLimits":[]},"unsupportedKeys":[]}
 * Every member is required.
 *
 * STUB: red phase. No behavior yet.
 */
object PortableSettingsCodec {
    fun encode(settings: PortableSettings): ByteArray = byteArrayOf()

    fun decode(bytes: ByteArray, limits: DecodeLimits = DecodeLimits()): DecodeResult =
        DecodeResult.Invalid(PortableSettingsError(PortableSettingsErrorCode.MALFORMED_JSON, "document"))
}
=== LegacySettingsConverter
package ly.com.tahaben.settings_portability

/**
 * Checks meaning the pure module cannot know: schedule JSON, enum names and similar. The Android side
 * implements it with the existing ScheduleCodec and domain enums. Returns the first problem, or null.
 */
fun interface SemanticValidator {
    fun firstProblem(configuration: SettingsConfiguration): SemanticProblem?
}

/** Names the setting only. Never carries its value. */
data class SemanticProblem(val store: SettingsStoreId, val key: String)

/** What the rescue helper reads out of the copied source: raw files plus the already-decoded typed stores. */
data class LegacySourceSnapshot(
    val source: PortableSource,
    /** Raw `shared_prefs/shared_pref.xml`. */
    val sharedPreferencesXml: String,
    /** DataStore decoded through the public DataStore API by an adapter; not protobuf bytes. */
    val dataStore: Map<String, SettingValue>,
    /** Result of selecting only the configuration rows from the copied database. */
    val rows: ConfigurationRows,
)

/**
 * Old app files -> portable settings. Parses legacy SharedPreferences XML strictly and applies [SettingsCatalog].
 *
 * Invariants:
 *  - CLAIM(catalog-only): only catalog Configuration keys reach the output. Excluded keys are named in the
 *    report; unknown keys are named in unsupportedKeys; neither value is carried.
 *  - CLAIM(types-kept): each value keeps its original type (long stays long, set stays set).
 *  - CLAIM(no-silent-default): XML defects, a duplicate name, a type that disagrees with the catalog, an
 *    unknown element, or a semantic problem yield Failed. Nothing is replaced with a default.
 *  - Schedule JSON and legacy schedule keys are kept verbatim. The app's own lazy migration (ScheduleCodec and
 *    DaySchedule.repairLegacy on first read) upgrades them; [SemanticValidator] rejects an undecodable one now.
 *
 * STUB: red phase. No behavior yet.
 */
object LegacySettingsConverter {
    fun convert(snapshot: LegacySourceSnapshot, validator: SemanticValidator): PortableSettingsResult =
        PortableSettingsResult.Ready(
            PortableSettings(snapshot.source, SettingsConfiguration()),
            ConversionReport(emptySet()),
        )
}
=== SettingsStores
package ly.com.tahaben.settings_portability

/**
 * A key-value store (SharedPreferences or DataStore) as the importer sees it. Adapters stay dumb: the shared
 * code decides which keys belong to the configuration domain, via [SettingsCatalog].
 */
interface PreferencesStore {
    /** Every key in the store, settings and internals alike. */
    fun readAll(): Map<String, SettingValue>

    /**
     * Removes [removeKeys] and writes [put] as one atomic, durable commit. Idempotent. Throws on failure.
     * Must not touch any other key.
     */
    fun apply(removeKeys: Set<String>, put: Map<String, SettingValue>)
}

/** The configuration rows (`apps_db`, `TimeLimitEntity`). Never the history tables. */
interface ConfigurationRowsStore {
    fun read(): ConfigurationRows

    /** Replaces both tables in one transaction. Idempotent. Throws on failure, leaving the old rows. */
    fun replace(rows: ConfigurationRows)
}

/** The smallest SQL surface the shared code needs. Android adapters wrap SQLiteDatabase; tests wrap JDBC. */
interface SqlSession {
    /** Each row is a list of Long, String or null in select-list order. */
    fun query(sql: String, args: List<Any?> = emptyList()): List<List<Any?>>
    fun execute(sql: String, args: List<Any?> = emptyList())
}

interface SqlTransactionRunner {
    /** Commits when [block] returns, rolls back when it throws. */
    fun <T> inTransaction(block: (SqlSession) -> T): T
}

/**
 * [ConfigurationRowsStore] over SQL. Touches only `apps_db` and `TimeLimitEntity`.
 *
 * CLAIM(config-sql-only): no statement names any other table, so history survives a replace [SqlConfigurationRowsStoreTest].
 * CLAIM(rows-atomic): delete and insert commit together or not at all [SqlConfigurationRowsStoreTest].
 *
 * STUB: red phase. No behavior yet.
 */
class SqlConfigurationRowsStore(private val runner: SqlTransactionRunner) : ConfigurationRowsStore {
    override fun read(): ConfigurationRows = ConfigurationRows()
    override fun replace(rows: ConfigurationRows) = Unit
}
=== ImportJournal
package ly.com.tahaben.settings_portability

enum class SettingsComponent {
    // Declaration order is the apply order: SQL first (transactional), the preference stores after.
    CONFIGURATION_ROWS,
    DATA_STORE,
    SHARED_PREFERENCES,
}

enum class FailureReason {
    /** A store threw while applying or restoring. */
    STORE_FAILED,

    /** The process died while the import was applying. Nothing says which stores were written. */
    INTERRUPTED,

    /** The current settings could not be read, so nothing was changed. */
    PREVIOUS_UNREADABLE,

    /** A journal exists but cannot be decoded. Only [StartupResult.RecoveryRequired] carries this. */
    JOURNAL_UNREADABLE,
}

/** [component] is set for STORE_FAILED. Carries no exception text, which could include values. */
data class ImportFailure(val reason: FailureReason, val component: SettingsComponent? = null)

data class ImportPreview(
    val source: PortableSource,
    val sharedPreferenceCount: Int,
    val dataStoreCount: Int,
    val appActivityRowCount: Int,
    val timeLimitRowCount: Int,
    val unsupportedKeys: List<UnsupportedKey>,
)

/**
 * The durable record of one import. Each case holds only what its phase needs, so an Applying journal without a
 * previous configuration cannot exist.
 *
 * Staged -> Applying -> Applied
 *                   \-> RollingBack -> RolledBack
 * Applied and RolledBack stay until [ImportCoordinator.acknowledge], so a crash after the work still shows the
 * outcome. That is at-least-once reporting; there is no exactly-once promise.
 */
sealed interface ImportJournal {
    data class Staged(val desired: SettingsConfiguration, val preview: ImportPreview) : ImportJournal
    data class Applying(
        val previous: SettingsConfiguration,
        val desired: SettingsConfiguration,
        val preview: ImportPreview,
    ) : ImportJournal
    data class RollingBack(val previous: SettingsConfiguration, val failure: ImportFailure) : ImportJournal
    data class Applied(val preview: ImportPreview) : ImportJournal
    data class RolledBack(val failure: ImportFailure) : ImportJournal
}

/** Read found bytes it cannot decode. Must never be reported as "no journal". */
class JournalUnreadableException(cause: Throwable? = null) : Exception("Import journal is unreadable", cause)

/** Lives under no_backup. [write] returns only after the record is durable and replaces the old one atomically. */
interface ImportJournalStorage {
    /** Null only when no journal exists. Throws [JournalUnreadableException] when one exists but cannot be read. */
    fun read(): ImportJournal?
    fun write(journal: ImportJournal)
    fun clear()
}
=== ImportCoordinator
package ly.com.tahaben.settings_portability

sealed interface StageResult {
    /** Validated and journaled. No store has changed. The app now asks the owner to close and reopen. */
    data class Staged(val preview: ImportPreview) : StageResult
    data class Rejected(val error: PortableSettingsError) : StageResult
    data class NotStaged(val reason: NotStagedReason) : StageResult
}

enum class NotStagedReason { IMPORT_IN_PROGRESS, JOURNAL_UNAVAILABLE }

sealed interface StartupResult {
    /** True only when the app may initialize stores, workers and screens. */
    val allowsNormalOperation: Boolean

    data object NoImport : StartupResult { override val allowsNormalOperation get() = true }
    data class Applied(val preview: ImportPreview) : StartupResult { override val allowsNormalOperation get() = true }
    data class RolledBack(val failure: ImportFailure) : StartupResult { override val allowsNormalOperation get() = true }

    /** Rollback or the journal itself failed. Stores may be mixed. Show recovery UI; call startup again to retry. */
    data class RecoveryRequired(val failure: ImportFailure) : StartupResult {
        override val allowsNormalOperation get() = false
    }
}

/**
 * Stages, applies and recovers a full settings replace across the three stores.
 *
 * Usage: [stage] while the app runs; [startup] first thing in the next process, before Hilt-created stores,
 * WorkManager or any screen reads settings.
 *
 * Invariants:
 *  - CLAIM(stage-no-write): stage never changes a store; an invalid file changes nothing.
 *  - CLAIM(domain-replace): apply removes catalog Configuration keys absent from the desired set and leaves every
 *    other key (internal flags, usage counters) untouched. Destination automation is an import-reset domain,
 *    separate from transferable configuration: the same preferences commit removes its credential and receipts
 *    and writes enabled=false. Previous captures these raw values too, so rollback restores them exactly.
 *  - CLAIM(journal-first): the Applying record, which holds previous and desired, is durable before the first
 *    store changes.
 *  - CLAIM(rollback-on-doubt): a thrown store failure or an interrupted Applying journal selects rollback.
 *    Rollback restores every component from the journaled previous configuration.
 *  - CLAIM(all-or-previous): after startup returns a result that allows normal operation, every component holds
 *    the desired configuration or every component holds the previous one.
 *  - CLAIM(blocked-not-success): if rollback fails or the journal is unreadable the result is RecoveryRequired,
 *    the journal stays RollingBack (or unreadable) and acknowledge refuses; success is never reported.
 *  - Catches Exception from ports. An Error (including a simulated process death) propagates untouched.
 *
 * STUB: red phase. No behavior yet.
 */
class ImportCoordinator(
    private val journal: ImportJournalStorage,
    private val sharedPreferences: PreferencesStore,
    private val dataStore: PreferencesStore,
    private val rows: ConfigurationRowsStore,
    private val validator: SemanticValidator,
) {
    /** Decode, catalog-check and semantic-check [fileBytes], then journal it as Staged. Replaces an older Staged.
     * Refuses Applying, RollingBack and unacknowledged terminal outcomes without a durable mutation.
     */
    fun stage(fileBytes: ByteArray, limits: DecodeLimits = DecodeLimits()): StageResult =
        StageResult.NotStaged(NotStagedReason.JOURNAL_UNAVAILABLE)

    /** Drives any journal to a terminal phase. Idempotent: safe to call again after a crash or a RecoveryRequired. */
    fun startup(): StartupResult = StartupResult.NoImport

    /** True while an Applying or RollingBack journal exists, or the journal cannot be read. */
    fun blocksNormalOperation(): Boolean = false

    /** Clears an Applied or RolledBack journal. Throws IllegalStateException in any other state. */
    fun acknowledge() = Unit
}

/** Normal-app export. Reads the three stores and keeps catalog Configuration keys only. */
object SettingsExporter {
    fun export(
        source: PortableSource,
        sharedPreferences: PreferencesStore,
        dataStore: PreferencesStore,
        rows: ConfigurationRowsStore,
        validator: SemanticValidator,
    ): PortableSettingsResult = PortableSettingsResult.Ready(
        PortableSettings(source, SettingsConfiguration()),
        ConversionReport(emptySet()),
    )
}

