package ly.com.tahaben.settings_portability

import java.io.IOException

/** Stands in for the process dying. An Error, so a coordinator that catches Exception cannot swallow it. */
class SimulatedProcessDeath : Error("simulated process death")

/**
 * The shared "disk". Every durable mutation (journal write or clear, store apply or replace) calls
 * [beforeMutation] first, so one counter orders all of them across stores and journal.
 */
class Faults {
    var operations = 0
        private set
    var crashAtOperation: Int? = null
    var tearOnCrash = false

    fun beforeMutation(tear: () -> Unit) {
        operations++
        if (crashAtOperation == operations) {
            if (tearOnCrash) tear()
            throw SimulatedProcessDeath()
        }
    }
}

class FakePreferencesStore(
    private val faults: Faults,
    initial: Map<String, SettingValue>,
) : PreferencesStore {
    var contents: Map<String, SettingValue> = initial
        private set
    /** Fails an apply whose [apply] `put` matches. Keyed on the value so a replayed restore is not caught by it. */
    var failWhen: (Map<String, SettingValue>) -> Boolean = { false }
    var failReads = false

    override fun readAll(): Map<String, SettingValue> {
        if (failReads) throw IOException("injected read failure")
        return contents
    }

    override fun apply(removeKeys: Set<String>, put: Map<String, SettingValue>) {
        // A torn write: the process dies after the removals and half of the puts reached the file.
        faults.beforeMutation {
            contents = (contents - removeKeys) + put.entries.sortedBy { it.key }.take((put.size + 1) / 2).associate { it.key to it.value }
        }
        if (failWhen(put)) throw IOException("injected store failure")
        contents = (contents - removeKeys) + put
    }
}

class FakeRowsStore(
    private val faults: Faults,
    initial: ConfigurationRows,
) : ConfigurationRowsStore {
    var contents: ConfigurationRows = initial
        private set
    var failWhen: (ConfigurationRows) -> Boolean = { false }

    override fun read(): ConfigurationRows = contents

    override fun replace(rows: ConfigurationRows) {
        // A torn write: only the first table reached disk.
        faults.beforeMutation { contents = contents.copy(apps = rows.apps) }
        if (failWhen(rows)) throw IOException("injected store failure")
        contents = rows
    }
}

class FakeJournalStorage(private val faults: Faults) : ImportJournalStorage {
    var current: ImportJournal? = null
        private set
    var unreadable = false

    override fun read(): ImportJournal? {
        if (unreadable) throw JournalUnreadableException()
        return current
    }

    override fun write(journal: ImportJournal) {
        faults.beforeMutation { }
        current = journal
    }

    override fun clear() {
        faults.beforeMutation { }
        current = null
    }
}

val ImportJournal?.phaseName: String get() = this?.let { it::class.simpleName } ?: "None"

/** Document builder for hand-written inputs. Content is literal; this only assembles the envelope. */
object Json {
    const val NO_GROUPS =
        """{"booleans":{},"ints":{},"longs":{},"floats":{},"doubles":{},"strings":{},"stringSets":{}}"""

    fun groups(
        booleans: String = "",
        ints: String = "",
        longs: String = "",
        floats: String = "",
        doubles: String = "",
        strings: String = "",
        stringSets: String = "",
    ) = """{"booleans":{$booleans},"ints":{$ints},"longs":{$longs},"floats":{$floats},"doubles":{$doubles},""" +
        """"strings":{$strings},"stringSets":{$stringSets}}"""

    const val SOURCE =
        """{"packageName":"ly.com.tahaben.farhan_alpha","versionName":"0.2.6-alpha","versionCode":11,"userId":0}"""

    fun document(
        version: String = "1",
        shared: String = NO_GROUPS,
        dataStore: String = NO_GROUPS,
        apps: String = "",
        timeLimits: String = "",
        unsupported: String = "",
        format: String = "farhan-settings",
    ) = """{"format":"$format","version":$version,"source":$SOURCE,"sharedPreferences":$shared,"dataStore":$dataStore,""" +
        """"configurationRows":{"apps":[$apps],"timeLimits":[$timeLimits]},"unsupportedKeys":[$unsupported]}"""
}

package ly.com.tahaben.settings_portability

import com.google.common.truth.Truth.assertThat
import com.google.common.truth.Truth.assertWithMessage
import ly.com.tahaben.settings_portability.SettingValue.Bool
import ly.com.tahaben.settings_portability.SettingValue.Float32
import ly.com.tahaben.settings_portability.SettingValue.Float64
import ly.com.tahaben.settings_portability.SettingValue.Int32
import ly.com.tahaben.settings_portability.SettingValue.Int64
import ly.com.tahaben.settings_portability.SettingValue.Text
import ly.com.tahaben.settings_portability.SettingValue.TextSet
import org.junit.Test

/**
 * The file format against literal text. Encoder and decoder are mated parts, so each is checked against the same
 * hand-written document rather than only against each other (technical-excellence: parity tests).
 * The keys here are arbitrary on purpose: the codec checks structure, the catalog checks meaning.
 */
class PortableSettingsCodecTest {

    private val source = PortableSource("ly.com.tahaben.farhan_alpha", "0.2.6-alpha", 11L, 0)

    /** The canonical text version 1 produces. Compact, fixed member order, sorted keys. Reviewed by hand. */
    private val canonicalFile =
        """{"format":"farhan-settings","version":1,""" +
            """"source":{"packageName":"ly.com.tahaben.farhan_alpha","versionName":"0.2.6-alpha","versionCode":11,"userId":0},""" +
            """"sharedPreferences":{"booleans":{"a_flag":true},"ints":{"count":-7},""" +
            """"longs":{"beyond_double":9007199254740993,"big":9223372036854775807,"low":-9223372036854775808},""" +
            """"floats":{"ratio":1.5},"doubles":{"precise":0.1},"strings":{"quote":"say \"hi\" é"},""" +
            """"stringSets":{"set":["a","b","c"]}},""" +
            """"dataStore":{"booleans":{"app_main_switch":false},"ints":{"key_delayed_launch_duration":5},"longs":{},""" +
            """"floats":{},"doubles":{},"strings":{"app_theme_colors":"Classic"},""" +
            """"stringSets":{"key_delayed_launch_messages":["one","two"]}},""" +
            """"configurationRows":{"apps":[""" +
            """{"appName":"Alpha","packageName":"com.example.a","activityName":"com.example.a.Main","userSerial":0},""" +
            """{"appName":"Beta","packageName":"com.example.b","activityName":"com.example.b.Main","userSerial":10}],""" +
            """"timeLimits":[{"packageName":"com.example.a","timeLimitInMilli":3600000,"timeAtAddingInMilli":1700000000000}]},""" +
            """"unsupportedKeys":[{"store":"dataStore","key":"alpha"},{"store":"sharedPreferences","key":"zeta"}]}"""

    private val alpha = AppActivityRow("Alpha", "com.example.a", "com.example.a.Main", 0L)
    private val beta = AppActivityRow("Beta", "com.example.b", "com.example.b.Main", 10L)
    private val timeLimit = TimeLimitRow("com.example.a", 3_600_000L, 1_700_000_000_000L)

    private val sharedValues = listOf(
        "a_flag" to Bool(true),
        "count" to Int32(-7),
        "big" to Int64(Long.MAX_VALUE),
        "low" to Int64(Long.MIN_VALUE),
        "beyond_double" to Int64(9007199254740993L), // 2^53 + 1: a double would store 9007199254740992
        "ratio" to Float32(1.5f),
        "precise" to Float64(0.1),
        "quote" to Text("say \"hi\" é"),
        "set" to TextSet(setOf("c", "a", "b")),
    )
    private val dataStoreValues = listOf(
        "key_delayed_launch_messages" to TextSet(setOf("two", "one")),
        "app_theme_colors" to Text("Classic"),
        "key_delayed_launch_duration" to Int32(5),
        "app_main_switch" to Bool(false),
    )

    /** Built in scrambled order so only the encoder can produce the canonical order. */
    private val scrambled = PortableSettings(
        source,
        SettingsConfiguration(
            sharedPreferences = linkedMapOf<String, SettingValue>().apply { sharedValues.reversed().forEach { put(it.first, it.second) } },
            dataStore = linkedMapOf<String, SettingValue>().apply { dataStoreValues.forEach { put(it.first, it.second) } },
            rows = ConfigurationRows(apps = listOf(beta, alpha), timeLimits = listOf(timeLimit)),
        ),
        unsupportedKeys = listOf(UnsupportedKey(SettingsStoreId.SHARED_PREFERENCES, "zeta"), UnsupportedKey(SettingsStoreId.DATA_STORE, "alpha")),
    )

    private val decodedCanonical = PortableSettings(
        source,
        SettingsConfiguration(
            sharedPreferences = sharedValues.toMap(),
            dataStore = dataStoreValues.toMap(),
            rows = ConfigurationRows(apps = listOf(alpha, beta), timeLimits = listOf(timeLimit)),
        ),
        unsupportedKeys = listOf(UnsupportedKey(SettingsStoreId.DATA_STORE, "alpha"), UnsupportedKey(SettingsStoreId.SHARED_PREFERENCES, "zeta")),
    )

    private fun DecodeResult.valid(): PortableSettings {
        assertThat(this).isInstanceOf(DecodeResult.Valid::class.java)
        return (this as DecodeResult.Valid).settings
    }

    private fun DecodeResult.errorCode(): PortableSettingsErrorCode {
        assertThat(this).isInstanceOf(DecodeResult.Invalid::class.java)
        return (this as DecodeResult.Invalid).error.code
    }

    // why: backups must be byte-stable and exact. Longs beyond 2^53, the extremes, string-set order and escapes
    //      are where a JSON library or a hash-ordered set silently changes data.
    // proves: CLAIM(lossless-long), CLAIM(deterministic-file)
    // catches: writing longs as doubles (...992); Long.MIN_VALUE overflow; set or map order following insertion
    //          or hash order; rows left unsorted; non-UTF-8 output; "1.5" written as "1.5E0".
    @Test
    fun `the encoder writes the canonical file exactly`() {
        assertThat(String(PortableSettingsCodec.encode(scrambled), Charsets.UTF_8)).isEqualTo(canonicalFile)
    }

    // why: the decoder must read the same literal back to exact typed values, and must not depend on whitespace
    //      (a person may pretty-print or edit the file). Checked against text, not against the encoder.
    // proves: CLAIM(lossless-long)
    // catches: parsing numbers through double; confusing the int and long groups; losing the unsupported list.
    @Test
    fun `the decoder reads the literal file and a reformatted copy to the same typed values`() {
        assertThat(PortableSettingsCodec.decode(canonicalFile.toByteArray(Charsets.UTF_8)).valid()).isEqualTo(decodedCanonical)

        val reformatted = canonicalFile.replace(",", ",\n  ").replace("{", "{\n    ").replace(":", " : ")
        assertThat(reformatted).isNotEqualTo(canonicalFile) // the probe changed the text
        assertThat(PortableSettingsCodec.decode(reformatted.toByteArray(Charsets.UTF_8)).valid()).isEqualTo(decodedCanonical)
    }

    // why: a file that is damaged, from a newer format, ambiguous or oversized must yield a named error and no
    //      partial value. A key present twice would otherwise be resolved silently by whichever parser runs.
    // proves: CLAIM(strict-input)
    // catches: last-wins duplicate keys (platform JSONObject behavior); accepting version 2; "5" accepted as an int;
    //          1.5 truncated to an int; a long above Long.MAX_VALUE wrapped; trailing data ignored; limits checked
    //          after allocation or off by one. The accepted-at-limit controls show each limit is a boundary.
    @Test
    fun `defective files are rejected with the specific error`() {
        fun shared(groups: String) = Json.document(shared = groups)
        val cases = listOf(
            Triple("truncated", canonicalFile.dropLast(30), PortableSettingsErrorCode.MALFORMED_JSON),
            Triple("not json", "hello", PortableSettingsErrorCode.MALFORMED_JSON),
            Triple("trailing data", canonicalFile + "{}", PortableSettingsErrorCode.MALFORMED_JSON),
            Triple("other format", Json.document(format = "something-else"), PortableSettingsErrorCode.WRONG_FORMAT),
            Triple("version 2", Json.document(version = "2"), PortableSettingsErrorCode.UNSUPPORTED_VERSION),
            Triple("version 0", Json.document(version = "0"), PortableSettingsErrorCode.UNSUPPORTED_VERSION),
            Triple("duplicate member", shared(Json.groups(booleans = """"a":true,"a":false""")), PortableSettingsErrorCode.DUPLICATE_KEY),
            Triple(
                "same key in two type groups",
                shared(Json.groups(ints = """"a":1""", longs = """"a":1""")),
                PortableSettingsErrorCode.DUPLICATE_KEY,
            ),
            Triple("duplicate set element", shared(Json.groups(stringSets = """"a":["x","x"]""")), PortableSettingsErrorCode.DUPLICATE_KEY),
            Triple("string in ints", shared(Json.groups(ints = """"a":"5"""")), PortableSettingsErrorCode.TYPE_MISMATCH),
            Triple("fraction in ints", shared(Json.groups(ints = """"a":1.5""")), PortableSettingsErrorCode.TYPE_MISMATCH),
            Triple("exponent in longs", shared(Json.groups(longs = """"a":1e3""")), PortableSettingsErrorCode.TYPE_MISMATCH),
            Triple("string in booleans", shared(Json.groups(booleans = """"a":"true"""")), PortableSettingsErrorCode.TYPE_MISMATCH),
            Triple("int above Int.MAX_VALUE", shared(Json.groups(ints = """"a":2147483648""")), PortableSettingsErrorCode.OUT_OF_RANGE),
            Triple("long above Long.MAX_VALUE", shared(Json.groups(longs = """"a":9223372036854775808""")), PortableSettingsErrorCode.OUT_OF_RANGE),
        )
        assertThat(cases.map { it.first }).containsAtLeast(
            "truncated", "trailing data", "version 2", "duplicate member", "same key in two type groups", "long above Long.MAX_VALUE",
        )
        for ((name, text, code) in cases) {
            assertWithMessage(name).that(PortableSettingsCodec.decode(text.toByteArray(Charsets.UTF_8)).errorCode()).isEqualTo(code)
        }

        // limits: each accepted exactly at the limit and rejected one past it.
        val threeInts = shared(Json.groups(ints = """"a":1,"b":2,"c":3"""))
        val bytes = threeInts.toByteArray(Charsets.UTF_8)
        assertThat(PortableSettingsCodec.decode(bytes, DecodeLimits(maxEntries = 3)).valid().configuration.sharedPreferences).hasSize(3)
        assertThat(PortableSettingsCodec.decode(bytes, DecodeLimits(maxEntries = 2)).errorCode()).isEqualTo(PortableSettingsErrorCode.TOO_MANY_ENTRIES)
        assertThat(PortableSettingsCodec.decode(bytes, DecodeLimits(maxBytes = bytes.size)).valid()).isNotNull()
        assertThat(PortableSettingsCodec.decode(bytes, DecodeLimits(maxBytes = bytes.size - 1)).errorCode()).isEqualTo(PortableSettingsErrorCode.TOO_LARGE)

        val nestedSet = shared(Json.groups(stringSets = """"a":[["x"]]"""))
        assertThat(PortableSettingsCodec.decode(nestedSet.toByteArray(), DecodeLimits(maxDepth = 4)).errorCode()).isEqualTo(PortableSettingsErrorCode.TOO_DEEP)
        // All JSON keys and strings share the bound. Mandatory envelope tokens are shorter than 256.
        val longString = shared(Json.groups(strings = """"a":"${"x".repeat(256)}""""))
        assertThat(PortableSettingsCodec.decode(longString.toByteArray(), DecodeLimits(maxStringLength = 255)).errorCode()).isEqualTo(PortableSettingsErrorCode.TOO_LARGE)
        assertThat(PortableSettingsCodec.decode(longString.toByteArray(), DecodeLimits(maxStringLength = 256)).valid()).isNotNull()
    }
}

package ly.com.tahaben.settings_portability

import com.google.common.truth.Truth.assertThat
import org.junit.Assert.assertThrows
import org.junit.Test
import java.sql.Connection
import java.sql.DriverManager

/**
 * [SqlConfigurationRowsStore] against a real SQLite engine, with the table definitions copied from Room's exported
 * schema (app/schemas/ly.com.tahaben.farhan.db.FarhanDatabase/7.json). A recording fake would only mirror the SQL
 * text; here a statement that touches history actually deletes history.
 *
 * History rows hold synthetic text only.
 */
class SqlConfigurationRowsStoreTest {

    private val schema = listOf(
        "CREATE TABLE IF NOT EXISTS `apps_db` (`app_name` TEXT NOT NULL, `package_name` TEXT NOT NULL, `activity_name` TEXT NOT NULL, `user_serial` INTEGER NOT NULL, PRIMARY KEY(`app_name`, `package_name`))",
        "CREATE TABLE IF NOT EXISTS `TimeLimitEntity` (`packageName` TEXT NOT NULL, `timeLimitInMilli` INTEGER NOT NULL, `timeAtAddingInMilli` INTEGER NOT NULL, PRIMARY KEY(`packageName`))",
        "CREATE TABLE IF NOT EXISTS `NotificationItemEntity` (`id` TEXT NOT NULL, `appName` TEXT, `title` TEXT, `text` TEXT, `time` TEXT NOT NULL, `creatorPackage` TEXT NOT NULL, `timestamp` INTEGER NOT NULL DEFAULT 0, `priority` INTEGER NOT NULL DEFAULT 3, `category` TEXT NOT NULL DEFAULT 'OTHER', `isRead` INTEGER NOT NULL DEFAULT 0, `channelId` TEXT DEFAULT NULL, `isCleared` INTEGER NOT NULL DEFAULT 0, `isDelivered` INTEGER NOT NULL DEFAULT 0, `priorityReason` TEXT DEFAULT NULL, `sourceSession` TEXT NOT NULL DEFAULT '', `sourceEventOrder` INTEGER NOT NULL DEFAULT 0, `deliveryInvalidated` INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(`id`))",
        "CREATE TABLE IF NOT EXISTS `LaunchAttemptEntity` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `packageName` TEXT NOT NULL, `timestamp` INTEGER NOT NULL)",
        "CREATE TABLE IF NOT EXISTS `UsageDataItemEntity` (`app_name` TEXT NOT NULL, `package_name` TEXT NOT NULL, `usage_timestamp` INTEGER NOT NULL, `usage_type` TEXT NOT NULL, `app_category` TEXT, PRIMARY KEY(`usage_timestamp`))",
        "CREATE TABLE IF NOT EXISTS `DayLastUpdatedEntity` (`day` TEXT NOT NULL, `last_update_time` INTEGER NOT NULL, PRIMARY KEY(`day`))",
    )
    private val historyTables = listOf(
        "NotificationItemEntity", "LaunchAttemptEntity", "UsageDataItemEntity", "DayLastUpdatedEntity",
    )

    private val oldRows = ConfigurationRows(
        apps = listOf(AppActivityRow("Old", "com.old.app", "com.old.app.Main", 0L)),
        timeLimits = listOf(TimeLimitRow("com.old.app", 1_000L, 2_000L)),
    )

    private class JdbcSession(private val connection: Connection) : SqlSession {
        override fun query(sql: String, args: List<Any?>): List<List<Any?>> =
            connection.prepareStatement(sql).use { statement ->
                args.forEachIndexed { index, value -> statement.setObject(index + 1, value) }
                statement.executeQuery().use { results ->
                    val width = results.metaData.columnCount
                    buildList {
                        while (results.next()) {
                            // Contract: Long, String or null. The driver may hand back Integer for small numbers.
                            add((1..width).map { column ->
                                when (val value = results.getObject(column)) {
                                    is Number -> value.toLong()
                                    else -> value
                                }
                            })
                        }
                    }
                }
            }

        override fun execute(sql: String, args: List<Any?>) {
            connection.prepareStatement(sql).use { statement ->
                args.forEachIndexed { index, value -> statement.setObject(index + 1, value) }
                statement.executeUpdate()
            }
        }
    }

    private class JdbcRunner(private val connection: Connection) : SqlTransactionRunner {
        override fun <T> inTransaction(block: (SqlSession) -> T): T {
            connection.autoCommit = false
            try {
                val value = block(JdbcSession(connection))
                connection.commit()
                return value
            } catch (failure: Throwable) {
                connection.rollback()
                throw failure
            } finally {
                connection.autoCommit = true
            }
        }
    }

    private fun withDatabase(test: (Connection, SqlConfigurationRowsStore) -> Unit) {
        DriverManager.getConnection("jdbc:sqlite::memory:").use { connection ->
            connection.createStatement().use { statement ->
                schema.forEach { statement.execute(it) }
                statement.execute("INSERT INTO apps_db VALUES ('Old','com.old.app','com.old.app.Main',0)")
                statement.execute("INSERT INTO TimeLimitEntity VALUES ('com.old.app',1000,2000)")
                statement.execute("INSERT INTO NotificationItemEntity (id, appName, title, text, time, creatorPackage) VALUES ('n1','App','SYNTHETIC-TITLE','SYNTHETIC-TEXT','12:00','com.history.app')")
                statement.execute("INSERT INTO LaunchAttemptEntity (packageName, timestamp) VALUES ('com.history.app', 1700000000000)")
                statement.execute("INSERT INTO UsageDataItemEntity VALUES ('U','com.history.app',1700000000001,'SYNTHETIC',NULL)")
                statement.execute("INSERT INTO DayLastUpdatedEntity VALUES ('2026-11-17',1700000000002)")
            }
            test(connection, SqlConfigurationRowsStore(JdbcRunner(connection)))
        }
    }

    private fun Connection.dump(table: String): List<List<Any?>> = JdbcSession(this).query("SELECT * FROM `$table` ORDER BY 1")

    private fun Connection.historyDump(): Map<String, List<List<Any?>>> = historyTables.associateWith { dump(it) }

    // why: the owner's history must survive a settings restore, and the restore must set exactly the rows given,
    //      including values that overflow an int (user serial, epoch milliseconds).
    // proves: CLAIM(config-sql-only)
    // catches: DELETE without a table filter or a "clear all tables" helper; a read that returns the wrong column
    //          order; int truncation of epoch milliseconds; rows left from before the replace; unsorted reads.
    //          The raw SELECTs below do not go through the store under test.
    @Test
    fun `replace sets exactly the given configuration rows and leaves every history table untouched`() = withDatabase { connection, store ->
        val historyBefore = connection.historyDump()
        // positive control: the probe sees real history in all four tables
        assertThat(historyBefore.mapValues { it.value.size }).containsExactly(
            "NotificationItemEntity", 1, "LaunchAttemptEntity", 1, "UsageDataItemEntity", 1, "DayLastUpdatedEntity", 1,
        )
        assertThat(store.read()).isEqualTo(oldRows)

        val replacement = ConfigurationRows(
            apps = listOf(
                AppActivityRow("Zed", "com.example.zed", "com.example.zed.Main", 4_000_000_000L),
                AppActivityRow("Alpha", "com.example.alpha", "com.example.alpha.Main", 10L),
            ),
            timeLimits = listOf(
                TimeLimitRow("com.example.zed", 7_200_000L, 1_700_000_000_000L),
                TimeLimitRow("com.example.alpha", 60_000L, 1_700_000_000_001L),
            ),
        )

        store.replace(replacement)
        store.replace(replacement) // idempotent

        assertThat(connection.dump("apps_db")).containsExactly(
            listOf("Alpha", "com.example.alpha", "com.example.alpha.Main", 10L),
            listOf("Zed", "com.example.zed", "com.example.zed.Main", 4_000_000_000L),
        ).inOrder()
        assertThat(connection.dump("TimeLimitEntity")).containsExactly(
            listOf("com.example.alpha", 60_000L, 1_700_000_000_001L),
            listOf("com.example.zed", 7_200_000L, 1_700_000_000_000L),
        ).inOrder()
        assertThat(store.read()).isEqualTo(
            ConfigurationRows(
                apps = listOf(replacement.apps[1], replacement.apps[0]),
                timeLimits = listOf(replacement.timeLimits[1], replacement.timeLimits[0]),
            ),
        )
        assertThat(connection.historyDump()).isEqualTo(historyBefore)
    }

    // why: a restore that dies halfway through the rows must leave the old rows, not an empty or half table.
    // proves: CLAIM(rows-atomic)
    // catches: autocommit per statement; deleting outside the transaction; inserting apps and time limits in
    //          separate transactions. The second app repeats the first one's primary key, so SQLite itself fails.
    @Test
    fun `a failed replace leaves the previous rows and history in place`() = withDatabase { connection, store ->
        val historyBefore = connection.historyDump()
        val failing = ConfigurationRows(
            apps = listOf(
                AppActivityRow("Same", "com.example.same", "com.example.same.A", 0L),
                AppActivityRow("Same", "com.example.same", "com.example.same.B", 0L), // primary key repeats
            ),
            timeLimits = listOf(TimeLimitRow("com.example.same", 1L, 2L)),
        )

        assertThrows(Exception::class.java) { store.replace(failing) }

        assertThat(store.read()).isEqualTo(oldRows)
        assertThat(connection.historyDump()).isEqualTo(historyBefore)
    }
}

package ly.com.tahaben.settings_portability

import com.google.common.truth.Truth.assertThat
import ly.com.tahaben.settings_portability.SettingValue.Bool
import ly.com.tahaben.settings_portability.SettingValue.Int32
import ly.com.tahaben.settings_portability.SettingValue.Int64
import ly.com.tahaben.settings_portability.SettingValue.Text
import ly.com.tahaben.settings_portability.SettingValue.TextSet
import org.junit.Test

/**
 * Normal export is a second entry into the same format as rescue conversion, so it gets its own check:
 * "tested once, wired twice" is how a leak ships. Ends with a full cycle into an empty app.
 */
class SettingsExporterTest {

    private val credentialSentinel = "REDACTED"
    private val source = PortableSource("ly.com.tahaben.farhan_alpha", "0.2.6-alpha", 11L, 0)

    private val sharedContents: Map<String, SettingValue> = mapOf(
        "notification_priority_override_com.example.chat" to Text("HIGH"),
        "notification_channel_priority_offset_com.example.chat_direct" to Int32(-1),
        "notify_me_schedule_date" to Int64(9007199254740993L),
        "notification_filter_exceptions" to TextSet(setOf("com.example.a")),
        "notification_automation_credential_v1" to Text(credentialSentinel),
        "should_combine_db" to Bool(true),
        "today_usage_key" to Int64(42L),
    )
    private val dataStoreContents: Map<String, SettingValue> = mapOf(
        "app_theme_colors" to Text("Ocean"),
        "app_main_switch" to Bool(false),
    )
    private val rows = ConfigurationRows(
        apps = listOf(AppActivityRow("Chat", "com.example.chat", "com.example.chat.Main", 0L)),
        timeLimits = listOf(TimeLimitRow("com.example.chat", 3_600_000L, 1_700_000_000_000L)),
    )

    private val expectedShared: Map<String, SettingValue> = mapOf(
        "notification_priority_override_com.example.chat" to Text("HIGH"),
        "notification_channel_priority_offset_com.example.chat_direct" to Int32(-1),
        "notify_me_schedule_date" to Int64(9007199254740993L),
        "notification_filter_exceptions" to TextSet(setOf("com.example.a")),
    )

    // why: export must keep every setting from all three stores and nothing else. Reading a store "as is" would
    //      put the automation credential in a file the owner stores anywhere.
    // proves: CLAIM(catalog-only)
    // catches: exporting readAll(); forgetting the DataStore or the rows; leaking the credential or counters;
    //          reporting an export as complete while naming nothing omitted.
    @Test
    fun `export keeps the configuration of all three stores and drops secrets and counters`() {
        val faults = Faults()
        val result = SettingsExporter.export(
            source,
            FakePreferencesStore(faults, sharedContents),
            FakePreferencesStore(faults, dataStoreContents),
            FakeRowsStore(faults, rows),
            SemanticValidator { null },
        )

        assertThat(result).isInstanceOf(PortableSettingsResult.Ready::class.java)
        val ready = result as PortableSettingsResult.Ready
        assertThat(ready.settings.configuration).isEqualTo(SettingsConfiguration(expectedShared, dataStoreContents, rows))
        assertThat(ready.report.omitted.map { it.key }).containsExactly(
            "notification_automation_credential_v1", "should_combine_db", "today_usage_key",
        )
        assertThat(faults.operations).isEqualTo(0) // export only reads
    }

    // why: the three public paths must agree on one format. A file exported by the app must restore, through
    //      stage and startup, into an empty app with the same configuration and none of the excluded keys.
    // proves: CLAIM(domain-replace), CLAIM(lossless-long)
    // catches: exporter and importer disagreeing on the catalog or the file shape; a long changed on the way;
    //          a restore into a fresh app that creates keys the source never had.
    @Test
    fun `a file exported by the app restores into an empty app with the same configuration`() {
        val exported = SettingsExporter.export(
            source,
            FakePreferencesStore(Faults(), sharedContents),
            FakePreferencesStore(Faults(), dataStoreContents),
            FakeRowsStore(Faults(), rows),
            SemanticValidator { null },
        ) as PortableSettingsResult.Ready
        val fileBytes = PortableSettingsCodec.encode(exported.settings)

        val faults = Faults()
        val emptyShared = FakePreferencesStore(faults, emptyMap())
        val emptyDataStore = FakePreferencesStore(faults, emptyMap())
        val emptyRows = FakeRowsStore(faults, ConfigurationRows())
        val journal = FakeJournalStorage(faults)
        val validator = SemanticValidator { null }

        assertThat(ImportCoordinator(journal, emptyShared, emptyDataStore, emptyRows, validator).stage(fileBytes))
            .isInstanceOf(StageResult.Staged::class.java)
        val restarted = ImportCoordinator(journal, emptyShared, emptyDataStore, emptyRows, validator).startup()

        assertThat(restarted).isInstanceOf(StartupResult.Applied::class.java)
        assertThat(emptyShared.contents).isEqualTo(expectedShared + ("notification_automation_enabled_v1" to Bool(false)))
        assertThat(emptyDataStore.contents).isEqualTo(dataStoreContents)
        assertThat(emptyRows.contents).isEqualTo(rows)
    }

    private fun queueDocument(length: Int): String = (1..150).joinToString(prefix = "{", postfix = "}", separator = ",") {
        """"com.example.app$it":{"order":"OLDEST_FIRST","rank":$it}"""
    }.also { require(it.length < length) }.padEnd(length, ' ')

    private fun exportQueue(queue: String, validator: SemanticValidator): PortableSettingsResult = SettingsExporter.export(
        source,
        FakePreferencesStore(Faults(), mapOf("notification_app_queue_v1" to Text(queue))),
        FakePreferencesStore(Faults(), emptyMap()),
        FakeRowsStore(Faults(), ConfigurationRows()),
        validator,
    )

    // why: valid per-app queue settings can exceed the original 10,000-character default (review F6).
    // proves: CLAIM(catalog-only), CLAIM(strict-input)
    // catches: keeping the old default, dropping the queue, skipping semantic validation, or unreadable export.
    @Test
    fun `a 12000 character valid queue exports and decodes under the default limits`() {
        val queue = queueDocument(12_000)
        val seen = mutableListOf<SettingsConfiguration>()
        val result = exportQueue(queue, SemanticValidator { seen += it; null })
        assertThat(result).isInstanceOf(PortableSettingsResult.Ready::class.java)
        val settings = (result as PortableSettingsResult.Ready).settings
        assertThat(settings.configuration.sharedPreferences).containsExactly("notification_app_queue_v1", Text(queue))
        assertThat(seen).containsExactly(settings.configuration) // validator positive control
        val decoded = PortableSettingsCodec.decode(PortableSettingsCodec.encode(settings))
        assertThat(decoded).isEqualTo(DecodeResult.Valid(settings))
    }

    // why: a saved export must be importable; an over-cap value must fail before the SAF document is written.
    // proves: CLAIM(strict-input)
    // catches: exporting unlimited strings or trusting an encoder without checking default decode limits.
    @Test
    fun `an export over the default string cap fails with a named error`() {
        val result = exportQueue(queueDocument(262_145), SemanticValidator { null })
        assertThat(result).isInstanceOf(PortableSettingsResult.Failed::class.java)
        assertThat((result as PortableSettingsResult.Failed).error.code).isEqualTo(PortableSettingsErrorCode.TOO_LARGE)
    }

    // why: structurally valid settings can still be unacceptable to the destination app's schedule or enums.
    // proves: CLAIM(no-silent-default)
    // catches: exporter ignoring the SemanticValidator while importer rejects the resulting file.
    @Test
    fun `export invokes semantic validation and reports rejection`() {
        val queue = queueDocument(12_000)
        val seen = mutableListOf<SettingsConfiguration>()
        val result = exportQueue(queue, SemanticValidator {
            seen += it
            SemanticProblem(SettingsStoreId.SHARED_PREFERENCES, "notification_app_queue_v1")
        })
        assertThat(seen).containsExactly(SettingsConfiguration(sharedPreferences = mapOf("notification_app_queue_v1" to Text(queue))))
        assertThat(result).isEqualTo(PortableSettingsResult.Failed(
            PortableSettingsError(PortableSettingsErrorCode.SEMANTIC_REJECTED, "sharedPreferences/notification_app_queue_v1"),
        ))
    }
}

package ly.com.tahaben.settings_portability

import com.google.common.truth.Truth.assertThat
import com.google.common.truth.Truth.assertWithMessage
import ly.com.tahaben.settings_portability.SettingValue.Bool
import ly.com.tahaben.settings_portability.SettingValue.Int32
import ly.com.tahaben.settings_portability.SettingValue.Int64
import ly.com.tahaben.settings_portability.SettingValue.Text
import ly.com.tahaben.settings_portability.SettingValue.TextSet
import org.junit.Assert.assertThrows
import org.junit.Test

/**
 * The production import path: file bytes -> [ImportCoordinator.stage] -> restart -> [ImportCoordinator.startup],
 * over in-memory stores that share one operation counter so a crash can be placed between any two writes.
 * Each `rig.coordinator()` call is a new process over the same "disk".
 *
 * Expected values are literals below, not read back from the code under test. Secrets are synthetic sentinels.
 *
 * Cross-cutting by design: each case drives stage, apply, rollback and journal together.
 */
class ImportCoordinatorTest {

    // ---- literal fixtures -------------------------------------------------------------------------------

    private val credentialSentinel = "REDACTED"

    /** What the destination app holds before the import. Config keys, plus keys outside the replace domain. */
    private val previousShared: Map<String, SettingValue> = mapOf(
        "notification_service_stats" to Bool(false),
        "notification_flood_threshold" to Int32(3), // config, absent from the file: must be removed
        "notification_priority_override_com.old.app" to Text("LOW"), // config, absent from the file: removed
        "notification_automation_credential_v1" to Text(credentialSentinel), // reset on success, restored on rollback
        "notification_automation_enabled_v1" to Bool(true),
        "notification_automation_last_at_v1" to Int64(1_700_000_000_000L),
        "notification_automation_last_mode_v1" to Text("REPEATING"),
        "notification_automation_last_error_v1" to Text("NONE"),
        "should_combine_db" to Bool(true), // outside the domain
        "today_usage_key" to Int64(42L), // outside the domain
    )
    private val previousDataStore: Map<String, SettingValue> = mapOf(
        "app_theme_colors" to Text("Classic"),
        "key_mindful_launch_white_list" to TextSet(setOf("com.old.app")), // config, absent from file: removed
        "some_future_key" to Text("kept"), // not in the catalog: never touched
    )
    private val previousRows = ConfigurationRows(
        apps = listOf(AppActivityRow("Old", "com.old.app", "com.old.app.Main", 0L)),
        timeLimits = listOf(TimeLimitRow("com.old.app", 60_000L, 1L)),
    )

    /** The file. Hand-written; values differ from [previousShared] so a skipped write shows. */
    private val desiredFile = Json.document(
        shared = Json.groups(
            booleans = """"notification_service_stats":true,"notification_priority_locked_com.example.chat":true""",
            ints = """"notification_batch_window_minutes":45,"notification_channel_priority_offset_com.example.chat_direct":-1""",
            longs = """"notify_me_schedule_date":9007199254740993""",
            strings = """"notification_category_priority_SOCIAL":"LOW"""",
            stringSets = """"notification_filter_exceptions":["com.example.b","com.example.a"]""",
        ),
        dataStore = Json.groups(
            booleans = """"app_main_switch":false""",
            ints = """"key_delayed_launch_duration":9""",
            strings = """"app_theme_colors":"Ocean"""",
        ),
        apps = """{"appName":"Chat","packageName":"com.example.chat","activityName":"com.example.chat.Main","userSerial":0}""",
        timeLimits = """{"packageName":"com.example.chat","timeLimitInMilli":3600000,"timeAtAddingInMilli":1700000000000}""",
    )

    private val desiredSharedConfig: Map<String, SettingValue> = mapOf(
        "notification_service_stats" to Bool(true),
        "notification_priority_locked_com.example.chat" to Bool(true),
        "notification_batch_window_minutes" to Int32(45),
        "notification_channel_priority_offset_com.example.chat_direct" to Int32(-1),
        "notify_me_schedule_date" to Int64(9007199254740993L),
        "notification_category_priority_SOCIAL" to Text("LOW"),
        "notification_filter_exceptions" to TextSet(setOf("com.example.a", "com.example.b")),
    )
    private val desiredDataStoreConfig: Map<String, SettingValue> = mapOf(
        "app_main_switch" to Bool(false),
        "key_delayed_launch_duration" to Int32(9),
        "app_theme_colors" to Text("Ocean"),
    )
    private val desiredRows = ConfigurationRows(
        apps = listOf(AppActivityRow("Chat", "com.example.chat", "com.example.chat.Main", 0L)),
        timeLimits = listOf(TimeLimitRow("com.example.chat", 3_600_000L, 1_700_000_000_000L)),
    )

    /** Previous map minus its config keys, which the import must leave alone. */
    private val sharedOutsideDomain = previousShared.filterKeys {
        it in setOf("should_combine_db", "today_usage_key")
    }
    private val dataStoreOutsideDomain = previousDataStore.filterKeys { it == "some_future_key" }

    private val expectedSharedAfterImport = sharedOutsideDomain + desiredSharedConfig +
        ("notification_automation_enabled_v1" to Bool(false))
    private val expectedDataStoreAfterImport = dataStoreOutsideDomain + desiredDataStoreConfig

    private val expectedPreview = ImportPreview(
        source = PortableSource("ly.com.tahaben.farhan_alpha", "0.2.6-alpha", 11L, 0),
        sharedPreferenceCount = 7, // 2 booleans + 2 ints + 1 long + 1 string + 1 set
        dataStoreCount = 3,
        appActivityRowCount = 1,
        timeLimitRowCount = 1,
        unsupportedKeys = emptyList(),
    )

    private class Rig(
        shared: Map<String, SettingValue>,
        dataStore: Map<String, SettingValue>,
        rows: ConfigurationRows,
    ) {
        val faults = Faults()
        val shared = FakePreferencesStore(faults, shared)
        val dataStore = FakePreferencesStore(faults, dataStore)
        val rows = FakeRowsStore(faults, rows)
        val journal = FakeJournalStorage(faults)
        var validator = SemanticValidator { null }

        /** A new process over the same disk. */
        fun coordinator() = ImportCoordinator(journal, shared, dataStore, rows, validator)
    }

    private fun rig() = Rig(previousShared, previousDataStore, previousRows)

    // Failures are keyed on the value written, so only the forward apply of the desired configuration fails and a
    // replayed restore of the previous configuration is not caught by the same fault.
    private fun Rig.failApplyOfShared() { shared.failWhen = { "notification_batch_window_minutes" in it } }
    private fun Rig.failApplyOfDataStore() { dataStore.failWhen = { "key_delayed_launch_duration" in it } }
    private fun Rig.failApplyOfRows() { rows.failWhen = { it == desiredRows } }
    private fun Rig.failRestoreOfRows() { rows.failWhen = { it == previousRows } }

    private fun stagedRig(): Rig = rig().also {
        assertThat(it.coordinator().stage(desiredFile.toByteArray())).isEqualTo(StageResult.Staged(expectedPreview))
    }

    private fun Rig.assertStoresEqualPrevious() {
        assertThat(shared.contents).isEqualTo(previousShared)
        assertThat(dataStore.contents).isEqualTo(previousDataStore)
        assertThat(rows.contents).isEqualTo(previousRows)
    }

    private fun Rig.assertStoresEqualDesired() {
        assertThat(shared.contents).isEqualTo(expectedSharedAfterImport)
        assertThat(dataStore.contents).isEqualTo(expectedDataStoreAfterImport)
        assertThat(rows.contents).isEqualTo(desiredRows)
    }

    // ---- tests ------------------------------------------------------------------------------------------

    // why: an invalid or hostile file must change nothing, not even the journal (invariant: invalid imports change
    //      nothing). Each defect class is a separate entry point into the same stage seam.
    // proves: CLAIM(stage-no-write)
    // catches: validating after writing the journal or a store; a stage that skips the catalog or the validator;
    //          reporting the wrong class of error. The control proves the probe moves: the same stage call with the
    //          valid file does write, and exactly one journal record.
    @Test
    fun `a file that fails validation changes no store and writes no journal`() {
        val control = rig()
        assertThat(control.coordinator().stage(desiredFile.toByteArray())).isEqualTo(StageResult.Staged(expectedPreview))
        assertThat(control.journal.current.phaseName).isEqualTo("Staged")
        assertThat(control.faults.operations).isEqualTo(1) // the journal write is the only mutation
        control.assertStoresEqualPrevious() // staging alone never changes a store

        val duplicateMember = Json.document(shared = Json.groups(booleans = """"a":true,"a":false"""))
        val credentialInFile = Json.document(
            shared = Json.groups(strings = """"notification_automation_credential_v1":"$credentialSentinel""""),
        )
        val unknownSetting = Json.document(shared = Json.groups(strings = """"future_setting":"x""""))
        val wrongTypeForKnownKey = Json.document(shared = Json.groups(strings = """"notification_batch_window_minutes":"45""""))
        val validDocumentWithManyEntries = Json.document(
            shared = Json.groups(ints = """"notification_flood_threshold":1,"notification_batch_window_minutes":2,"notification_standing_threshold_hours":3,"infinite_scroll_time_out":4"""),
        )
        val cases: List<Triple<String, ByteArray, PortableSettingsErrorCode>> = listOf(
            Triple("truncated", desiredFile.dropLast(25).toByteArray(), PortableSettingsErrorCode.MALFORMED_JSON),
            Triple("duplicate member", duplicateMember.toByteArray(), PortableSettingsErrorCode.DUPLICATE_KEY),
            Triple("unknown version", Json.document(version = "2").toByteArray(), PortableSettingsErrorCode.UNSUPPORTED_VERSION),
            Triple("credential in file", credentialInFile.toByteArray(), PortableSettingsErrorCode.EXCLUDED_KEY),
            Triple("unknown setting", unknownSetting.toByteArray(), PortableSettingsErrorCode.UNSUPPORTED_KEY),
            Triple("type disagrees with catalog", wrongTypeForKnownKey.toByteArray(), PortableSettingsErrorCode.TYPE_MISMATCH),
        )
        assertThat(cases.map { it.first }).containsExactly(
            "truncated", "duplicate member", "unknown version", "credential in file", "unknown setting", "type disagrees with catalog",
        )
        for ((name, bytes, code) in cases) {
            val rig = rig()
            val result = rig.coordinator().stage(bytes)
            assertWithMessage(name).that(result).isInstanceOf(StageResult.Rejected::class.java)
            assertWithMessage(name).that((result as StageResult.Rejected).error.code).isEqualTo(code)
            rig.assertStoresEqualPrevious()
            assertWithMessage(name).that(rig.journal.current).isNull()
            assertWithMessage(name).that(rig.faults.operations).isEqualTo(0)
            assertWithMessage(name).that(rig.coordinator().blocksNormalOperation()).isFalse()
        }

        // limit: 4 entries accepted at exactly the limit, rejected one over.
        val atLimit = rig().coordinator().stage(validDocumentWithManyEntries.toByteArray(), DecodeLimits(maxEntries = 4))
        assertThat(atLimit).isInstanceOf(StageResult.Staged::class.java)
        val overLimitRig = rig()
        val overLimit = overLimitRig.coordinator().stage(validDocumentWithManyEntries.toByteArray(), DecodeLimits(maxEntries = 3))
        assertThat((overLimit as StageResult.Rejected).error.code).isEqualTo(PortableSettingsErrorCode.TOO_MANY_ENTRIES)
        assertThat(overLimitRig.faults.operations).isEqualTo(0)

        // meaning the pure module cannot check goes through the validator port.
        val semanticRig = rig().also {
            it.validator = SemanticValidator { configuration ->
                if (configuration.sharedPreferences.containsKey("notification_category_priority_SOCIAL")) {
                    SemanticProblem(SettingsStoreId.SHARED_PREFERENCES, "notification_category_priority_SOCIAL")
                } else null
            }
        }
        val semantic = semanticRig.coordinator().stage(desiredFile.toByteArray())
        assertThat(semantic).isEqualTo(
            StageResult.Rejected(
                PortableSettingsError(
                    PortableSettingsErrorCode.SEMANTIC_REJECTED,
                    "sharedPreferences/notification_category_priority_SOCIAL",
                ),
            ),
        )
        assertThat(semanticRig.faults.operations).isEqualTo(0)
    }

    // why: a valid import replaces exactly the configuration domain: stale config keys go, unrelated keys
    //      (internal flag, usage counter) and unknown keys stay. Per spec review F3, destination automation is
    //      revoked in the same commit; source secrets remain nontransferable. Report until acknowledged.
    // proves: CLAIM(domain-replace), CLAIM(journal-first)
    // catches: a restore that clears the whole store; one that only adds keys; a restore that deletes the
    //          credential only after Applied; clearing the journal before the owner is told; applying before restart.
    @Test
    fun `a staged import replaces exactly the configuration and reports until acknowledged`() {
        val rig = stagedRig()
        rig.assertStoresEqualPrevious()

        val result = rig.coordinator().startup()

        assertThat(result).isEqualTo(StartupResult.Applied(expectedPreview))
        assertThat(result.allowsNormalOperation).isTrue()
        rig.assertStoresEqualDesired()
        assertThat(rig.journal.current).isEqualTo(ImportJournal.Applied(expectedPreview))

        // A crash after the work must still show the outcome, and must not apply a second time.
        val operationsBefore = rig.faults.operations
        assertThat(rig.coordinator().startup()).isEqualTo(StartupResult.Applied(expectedPreview))
        assertThat(rig.faults.operations).isEqualTo(operationsBefore)
        rig.assertStoresEqualDesired()

        rig.coordinator().acknowledge()
        assertThat(rig.journal.current).isNull()
        assertThat(rig.coordinator().startup()).isEqualTo(StartupResult.NoImport)
    }

    // why: a store that fails while applying must send every component back to the previous configuration,
    //      including components already written, and must never be reported as applied.
    // proves: CLAIM(rollback-on-doubt), CLAIM(all-or-previous)
    // catches: rollback that restores only the failing store; rollback that skips stores already applied; a result
    //          or journal that says Applied after a failure. Each component is failed in turn, so the first store
    //          (nothing else written yet) and the last (everything else written) are both covered.
    @Test
    fun `a failure in any store rolls every store back to the previous settings`() {
        val cases = listOf(
            SettingsComponent.CONFIGURATION_ROWS to { rig: Rig -> rig.failApplyOfRows() },
            SettingsComponent.DATA_STORE to { rig: Rig -> rig.failApplyOfDataStore() },
            SettingsComponent.SHARED_PREFERENCES to { rig: Rig -> rig.failApplyOfShared() },
        )
        assertThat(cases.map { it.first }).containsExactly(
            SettingsComponent.CONFIGURATION_ROWS, SettingsComponent.DATA_STORE, SettingsComponent.SHARED_PREFERENCES,
        )
        for ((component, injectFailure) in cases) {
            val rig = stagedRig()
            injectFailure(rig)
            val failure = ImportFailure(FailureReason.STORE_FAILED, component)

            val result = rig.coordinator().startup()

            assertThat(result).isEqualTo(StartupResult.RolledBack(failure))
            assertThat(result.allowsNormalOperation).isTrue()
            rig.assertStoresEqualPrevious()
            assertThat(rig.journal.current).isEqualTo(ImportJournal.RolledBack(failure))
            assertThat(rig.coordinator().blocksNormalOperation()).isFalse()
        }
    }

    // why: the process can die between any two durable writes, including inside a store write. After the next
    //      startup every component must hold the desired configuration or every component the previous one, and
    //      while the journal says apply/rollback is in progress, normal operation must stay blocked.
    // proves: CLAIM(all-or-previous), CLAIM(rollback-on-doubt)
    // catches: journal written after the first store write; no replay of Applying; replay that rolls forward on a
    //          store that cannot finish; apply that never reaches a terminal journal; a gate that lets screens read
    //          while Applying or RollingBack is pending. Torn writes (half a store) are swept too.
    @Test
    fun `a crash at every durable write converges to all previous or all desired`() {
        val applied = StartupResult.Applied(expectedPreview)
        val failed = StartupResult.RolledBack(ImportFailure(FailureReason.STORE_FAILED, SettingsComponent.SHARED_PREFERENCES))
        val applyPhases = crashSweep(tear = false, stagedReplay = applied) { }
        val tornPhases = crashSweep(tear = true, stagedReplay = applied) { }
        // rollback path: shared preferences fails, then the process dies at each rollback write.
        val rollbackPhases = crashSweep(tear = false, stagedReplay = failed) { it.failApplyOfShared() }
        val tornRollbackPhases = crashSweep(tear = true, stagedReplay = failed) { it.failApplyOfShared() }

        // The sweeps must actually have landed in each phase, or the loop proves nothing.
        assertThat(applyPhases).containsAtLeast("Staged", "Applying")
        assertThat(tornPhases).containsAtLeast("Staged", "Applying")
        assertThat(rollbackPhases).containsAtLeast("Applying", "RollingBack")
        assertThat(tornRollbackPhases).containsAtLeast("Applying", "RollingBack")
    }

    private fun crashSweep(tear: Boolean, stagedReplay: StartupResult, configure: (Rig) -> Unit): Set<String> {
        val dry = stagedRig().also(configure)
        val before = dry.faults.operations
        dry.coordinator().startup()
        val operationsInRun = dry.faults.operations - before
        assertThat(operationsInRun).isAtLeast(5) // journal, three stores, journal

        val phasesSeen = mutableSetOf<String>()
        for (crashPoint in 1..operationsInRun) {
            val rig = stagedRig().also(configure)
            rig.faults.crashAtOperation = rig.faults.operations + crashPoint
            rig.faults.tearOnCrash = tear
            assertThrows("crash point $crashPoint", SimulatedProcessDeath::class.java) { rig.coordinator().startup() }
            rig.faults.crashAtOperation = null

            val persisted = rig.journal.current
            phasesSeen += persisted.phaseName
            val inProgress = persisted is ImportJournal.Applying || persisted is ImportJournal.RollingBack
            assertThat(rig.coordinator().blocksNormalOperation()).isEqualTo(inProgress)

            val result = rig.coordinator().startup()

            when (persisted) {
                is ImportJournal.Staged -> {
                    assertThat(result).isEqualTo(stagedReplay)
                    if (stagedReplay is StartupResult.Applied) rig.assertStoresEqualDesired()
                    else rig.assertStoresEqualPrevious()
                }
                is ImportJournal.Applying -> {
                    assertThat(result).isEqualTo(StartupResult.RolledBack(ImportFailure(FailureReason.INTERRUPTED)))
                    rig.assertStoresEqualPrevious()
                }
                is ImportJournal.RollingBack -> {
                    assertThat(result).isEqualTo(StartupResult.RolledBack(persisted.failure))
                    rig.assertStoresEqualPrevious()
                }
                else -> throw AssertionError("a crash cannot leave ${persisted.phaseName} at point $crashPoint")
            }
            assertThat(result.allowsNormalOperation).isTrue()
            assertThat(rig.coordinator().blocksNormalOperation()).isFalse()
        }
        return phasesSeen
    }

    // why: if rollback itself fails, the app must not run on mixed settings and must not claim success. It keeps
    //      a journal that a later start can finish.
    // proves: CLAIM(blocked-not-success)
    // catches: treating a failed restore as RolledBack; clearing the journal on any exit; acknowledge() clearing
    //          a journal that still needs recovery; a retry that cannot finish once the fault is gone; restoring
    //          nothing after the first failed restore.
    @Test
    fun `a failed rollback blocks startup keeps the journal and finishes on retry`() {
        val rig = stagedRig()
        rig.failApplyOfShared() // the apply fails at the last store
        rig.failRestoreOfRows() // and the restore of rows fails too
        val cause = ImportFailure(FailureReason.STORE_FAILED, SettingsComponent.SHARED_PREFERENCES)

        val blocked = rig.coordinator().startup()

        assertThat(blocked).isEqualTo(StartupResult.RecoveryRequired(cause))
        assertThat(blocked.allowsNormalOperation).isFalse()
        assertThat(rig.journal.current).isInstanceOf(ImportJournal.RollingBack::class.java)
        assertThat(rig.coordinator().blocksNormalOperation()).isTrue()
        assertThrows(IllegalStateException::class.java) { rig.coordinator().acknowledge() }
        assertThat(rig.journal.current).isInstanceOf(ImportJournal.RollingBack::class.java)
        // The other components were still restored; rows were not. The state is mixed, and says so by blocking.
        assertThat(rig.shared.contents).isEqualTo(previousShared)
        assertThat(rig.dataStore.contents).isEqualTo(previousDataStore)
        assertThat(rig.rows.contents).isEqualTo(desiredRows)

        // Same fault again: still blocked, never success.
        assertThat(rig.coordinator().startup()).isEqualTo(StartupResult.RecoveryRequired(cause))
        assertThat(rig.journal.current).isInstanceOf(ImportJournal.RollingBack::class.java)

        rig.rows.failWhen = { false }
        val recovered = rig.coordinator().startup()

        assertThat(recovered).isEqualTo(StartupResult.RolledBack(cause))
        rig.assertStoresEqualPrevious()
        assertThat(rig.journal.current).isEqualTo(ImportJournal.RolledBack(cause))
        assertThat(rig.coordinator().blocksNormalOperation()).isFalse()
    }

    // why: a journal that exists but cannot be read must stop startup. Reading it as "no import" would let the
    //      app run on whatever half-applied state a crash left.
    // proves: CLAIM(blocked-not-success)
    // catches: catching JournalUnreadableException and returning NoImport; staging over an unreadable journal.
    @Test
    fun `an unreadable journal blocks startup and is never read as no import`() {
        val rig = stagedRig()
        rig.coordinator().startup().also { assertThat(it).isInstanceOf(StartupResult.Applied::class.java) }
        rig.journal.unreadable = true
        val operationsBefore = rig.faults.operations

        val result = rig.coordinator().startup()

        assertThat(result).isEqualTo(StartupResult.RecoveryRequired(ImportFailure(FailureReason.JOURNAL_UNREADABLE)))
        assertThat(rig.coordinator().blocksNormalOperation()).isTrue()
        assertThat(rig.coordinator().stage(desiredFile.toByteArray())).isEqualTo(StageResult.NotStaged(NotStagedReason.JOURNAL_UNAVAILABLE))
        assertThat(rig.faults.operations).isEqualTo(operationsBefore)
    }

    // why: if the current settings cannot be read, there is nothing to roll back to, so the import must not start.
    // proves: CLAIM(journal-first)
    // catches: applying without a captured previous configuration; a crash path that still writes the stores.
    @Test
    fun `an unreadable current store stops the import before any store changes`() {
        val rig = stagedRig()
        rig.dataStore.failReads = true
        val operationsBefore = rig.faults.operations

        val result = rig.coordinator().startup()

        assertThat(result).isEqualTo(StartupResult.RolledBack(ImportFailure(FailureReason.PREVIOUS_UNREADABLE)))
        rig.dataStore.failReads = false
        rig.assertStoresEqualPrevious()
        // only the terminal journal record is written; no store was touched
        assertThat(rig.faults.operations - operationsBefore).isEqualTo(1)
        assertThat(rig.journal.current).isEqualTo(ImportJournal.RolledBack(ImportFailure(FailureReason.PREVIOUS_UNREADABLE)))
    }

    // why: replaying Staged after changing a store can silently roll forward from mixed state (review F2).
    // proves: CLAIM(journal-first), CLAIM(rollback-on-doubt)
    // catches: retaining Applying only in memory or persisting it after the first store commit.
    @Test
    fun `a crash after the first store commit retains Applying and rolls back on restart`() {
        val rig = stagedRig()
        // Applying journal, rows commit, then death before the DataStore commit.
        rig.faults.crashAtOperation = rig.faults.operations + 3
        assertThrows(SimulatedProcessDeath::class.java) { rig.coordinator().startup() }
        assertThat(rig.rows.contents).isEqualTo(desiredRows) // proves a store commit happened
        assertThat(rig.journal.current).isInstanceOf(ImportJournal.Applying::class.java)
        rig.faults.crashAtOperation = null
        assertThat(rig.coordinator().startup()).isEqualTo(StartupResult.RolledBack(ImportFailure(FailureReason.INTERRUPTED)))
        rig.assertStoresEqualPrevious()
    }

    // why: a new file must not erase pending recovery or an outcome the owner has not acknowledged (review F8).
    // proves: CLAIM(stage-no-write), CLAIM(blocked-not-success)
    // catches: overwriting Applying, RollingBack, Applied or RolledBack with a fresh Staged record.
    @Test
    fun `staging refuses in-progress and unacknowledged terminal journals without mutations`() {
        val previous = SettingsConfiguration(previousShared, previousDataStore, previousRows)
        val desired = SettingsConfiguration(desiredSharedConfig, desiredDataStoreConfig, desiredRows)
        val failure = ImportFailure(FailureReason.INTERRUPTED)
        val phases = listOf(
            ImportJournal.Applying(previous, desired, expectedPreview),
            ImportJournal.RollingBack(previous, failure),
            ImportJournal.Applied(expectedPreview),
            ImportJournal.RolledBack(failure),
        )
        assertThat(phases.map { it.phaseName }).containsExactly("Applying", "RollingBack", "Applied", "RolledBack")
        for (phase in phases) {
            val rig = rig()
            rig.journal.write(phase)
            val before = rig.faults.operations
            assertWithMessage(phase.phaseName).that(rig.coordinator().stage(desiredFile.toByteArray()))
                .isEqualTo(StageResult.NotStaged(NotStagedReason.IMPORT_IN_PROGRESS))
            assertThat(rig.faults.operations).isEqualTo(before)
            assertThat(rig.journal.current).isEqualTo(phase)
            rig.assertStoresEqualPrevious()
        }
    }

    // why: an older build's stored type is part of the previous snapshot even when today's catalog disagrees.
    // proves: CLAIM(all-or-previous)
    // catches: validating or coercing the previous configuration before journaling, losing an Int64 on rollback.
    @Test
    fun `rollback restores previous values with their raw stored types`() {
        val rawShared = previousShared + ("notification_flood_threshold" to Int64(9_007_199_254_740_993L))
        val rig = Rig(rawShared, previousDataStore, previousRows)
        assertThat(rig.coordinator().stage(desiredFile.toByteArray())).isEqualTo(StageResult.Staged(expectedPreview))
        rig.failApplyOfShared()
        assertThat(rig.coordinator().startup()).isEqualTo(
            StartupResult.RolledBack(ImportFailure(FailureReason.STORE_FAILED, SettingsComponent.SHARED_PREFERENCES)),
        )
        assertThat(rig.shared.contents).isEqualTo(rawShared)
        assertThat(rig.dataStore.contents).isEqualTo(previousDataStore)
        assertThat(rig.rows.contents).isEqualTo(previousRows)
    }

    // why: the owner may edit settings after staging; rollback must not discard those edits.
    // proves: CLAIM(all-or-previous), CLAIM(journal-first)
    // catches: capturing previous at staging instead of immediately before the cold-start apply.
    @Test
    fun `rollback uses settings edited between staging and restart`() {
        val rig = stagedRig()
        val edited = previousShared + ("notification_flood_threshold" to Int32(19))
        rig.shared.apply(emptySet(), mapOf("notification_flood_threshold" to Int32(19)))
        rig.failApplyOfShared()
        assertThat(rig.coordinator().startup()).isEqualTo(
            StartupResult.RolledBack(ImportFailure(FailureReason.STORE_FAILED, SettingsComponent.SHARED_PREFERENCES)),
        )
        assertThat(rig.shared.contents).isEqualTo(edited)
        assertThat(rig.dataStore.contents).isEqualTo(previousDataStore)
        assertThat(rig.rows.contents).isEqualTo(previousRows)
    }
}

